#!/usr/bin/env bash
# GSZ step127 — premium, responsive checkout redesign. Same form fields + scripts;
# upgraded header, trust strip, auto-numbered step cards, tighter layout, and on
# mobile the order summary moves to the top. Safe + idempotent; restores on fail.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step127-$TS"; TMP=$(mktemp -d)
F=views/checkout.ejs
echo "==> step127: premium checkout"
mkdir -p "$BK/$(dirname "$F")"; cp "$GSZ/$F" "$BK/$F"; echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; cp "$BK/$F" "$GSZ/$F"; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/checkout.ejs"
echo "==> validating new checkout.ejs"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$TMP/checkout.ejs','utf8'),{filename:'$GSZ/$F'});console.log('    ejs compiles ok')"
# guard: new file must still carry the critical hooks before we install it
for tok in 'name="method"' 'id="sumTotal"' '/*disc-js*/' 'name="proof"'; do grep -qF "$tok" "$TMP/checkout.ejs" || { echo "!! new checkout.ejs missing $tok"; false; }; done
cp "$TMP/checkout.ejs" "$GSZ/$F"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
SLUG=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASS,database:process.env.DB_NAME});p.query(\"SELECT slug FROM products WHERE active AND NOT hidden ORDER BY id LIMIT 1\").then(function(r){console.log(r.rows[0]?r.rows[0].slug:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SLUG" ]; then CC=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3900/checkout?p=$SLUG&plan=0&region=PK" || true); [ "$CC" = "200" ] && echo "    checkout renders ($SLUG): OK" || { echo "    checkout $CC"; false; }; fi
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step127 OK ✅  Premium checkout: secure header + trust strip, numbered steps, tighter cards, and on mobile the order summary shows first. All fields + payment/discount logic unchanged."
